def add(speaker, text, cites=None, span=None):
    u = {"speaker": speaker, "text": text, "citations": []}
    if cites:
        for c in cites:
            entry = {"source_id": c[0], "locator": c[1], "quote": c[2], "answer_span": span}
            u["citations"].append(entry)
    utterances.append(u)

